GRANT ALL ON SCHEMA coco_inventory__serialised_product_identifiers TO egeria_admin, egeria_user, airflow_user;
COMMENT ON SCHEMA coco_inventory__serialised_product_identifiers IS 'Subscription of Coco Inventory (Coco core, System::coco-inventory) to the digital product Serialised Product Identifiers (DigitalProduct::Coco::Serialised Product Identifiers): a copy of the product''s data set coco_data_hub.serialised_product_identifiers delivered for this subscriber. Basis: Goods Inventory Stock depends on it (serialised stock).';

CREATE TABLE IF NOT EXISTS coco_inventory__serialised_product_identifiers.serialised_identifier (
  pack_serial_number               varchar(40) NOT NULL,
  product_code                     varchar(20) NOT NULL,
  pack_code                        varchar(20) NOT NULL,
  batch_identifier                 varchar(40) NOT NULL,
  pack_expiry_date                 date NOT NULL,
  market_code                      varchar(8) NOT NULL,
  pack_current_status              varchar(20) NOT NULL,
  aggregation_parent_serial_number varchar(40),
  warehouse_code                   varchar(20),
  delivery_identifier              varchar(100) NOT NULL,
  delivery_timestamp               timestamptz NOT NULL DEFAULT now(),
  processing_status                varchar(20) NOT NULL DEFAULT 'delivered',
  processing_timestamp             timestamptz,
  processing_message               text,
  CONSTRAINT serialised_identifier_pk PRIMARY KEY (pack_serial_number)
);
COMMENT ON TABLE coco_inventory__serialised_product_identifiers.serialised_identifier IS 'One row per identifier, its current state. Delivered from coco_data_hub.serialised_product_identifiers.serialised_identifier.';
COMMENT ON COLUMN coco_inventory__serialised_product_identifiers.serialised_identifier.pack_serial_number IS 'The identifier.';
COMMENT ON COLUMN coco_inventory__serialised_product_identifiers.serialised_identifier.product_code IS 'The product.';
COMMENT ON COLUMN coco_inventory__serialised_product_identifiers.serialised_identifier.pack_code IS 'The presentation.';
COMMENT ON COLUMN coco_inventory__serialised_product_identifiers.serialised_identifier.batch_identifier IS 'The batch.';
COMMENT ON COLUMN coco_inventory__serialised_product_identifiers.serialised_identifier.pack_expiry_date IS 'The expiry.';
COMMENT ON COLUMN coco_inventory__serialised_product_identifiers.serialised_identifier.market_code IS 'The destination market.';
COMMENT ON COLUMN coco_inventory__serialised_product_identifiers.serialised_identifier.pack_current_status IS 'Allocated, commissioned, aggregated, shipped, decommissioned or destroyed.';
COMMENT ON COLUMN coco_inventory__serialised_product_identifiers.serialised_identifier.aggregation_parent_serial_number IS 'The case or pallet currently containing it.';
COMMENT ON COLUMN coco_inventory__serialised_product_identifiers.serialised_identifier.warehouse_code IS 'The location, while in stock.';
COMMENT ON COLUMN coco_inventory__serialised_product_identifiers.serialised_identifier.delivery_identifier IS 'The delivery (for example the pipeline run) that last wrote this row.';
COMMENT ON COLUMN coco_inventory__serialised_product_identifiers.serialised_identifier.delivery_timestamp IS 'When this row was last delivered from the digital product.';
COMMENT ON COLUMN coco_inventory__serialised_product_identifiers.serialised_identifier.processing_status IS 'delivered (waiting for the subscriber), processed, or failed. Set back to delivered to reprocess the row.';
COMMENT ON COLUMN coco_inventory__serialised_product_identifiers.serialised_identifier.processing_timestamp IS 'When the subscriber last processed this row, successfully or not.';
COMMENT ON COLUMN coco_inventory__serialised_product_identifiers.serialised_identifier.processing_message IS 'Why processing failed, or any note the subscriber records.';

CREATE TABLE IF NOT EXISTS coco_inventory__serialised_product_identifiers.identifier_event (
  pack_serial_number   varchar(40) NOT NULL,
  pack_event_timestamp timestamptz NOT NULL,
  pack_event_type      varchar(20) NOT NULL,
  system_identifier    varchar(60) NOT NULL,
  alert_identifier     varchar(40),
  delivery_identifier  varchar(100) NOT NULL,
  delivery_timestamp   timestamptz NOT NULL DEFAULT now(),
  processing_status    varchar(20) NOT NULL DEFAULT 'delivered',
  processing_timestamp timestamptz,
  processing_message   text,
  CONSTRAINT identifier_event_pk PRIMARY KEY (pack_serial_number, pack_event_timestamp)
);
COMMENT ON TABLE coco_inventory__serialised_product_identifiers.identifier_event IS 'One row per change of state of an identifier. Delivered from coco_data_hub.serialised_product_identifiers.identifier_event.';
COMMENT ON COLUMN coco_inventory__serialised_product_identifiers.identifier_event.pack_serial_number IS 'The identifier.';
COMMENT ON COLUMN coco_inventory__serialised_product_identifiers.identifier_event.pack_event_timestamp IS 'When.';
COMMENT ON COLUMN coco_inventory__serialised_product_identifiers.identifier_event.pack_event_type IS 'Commissioned, aggregated, shipped, verified, decommissioned, corrected.';
COMMENT ON COLUMN coco_inventory__serialised_product_identifiers.identifier_event.system_identifier IS 'The system that reported the event.';
COMMENT ON COLUMN coco_inventory__serialised_product_identifiers.identifier_event.alert_identifier IS 'The alert disposition that caused a correction, if any.';
COMMENT ON COLUMN coco_inventory__serialised_product_identifiers.identifier_event.delivery_identifier IS 'The delivery (for example the pipeline run) that last wrote this row.';
COMMENT ON COLUMN coco_inventory__serialised_product_identifiers.identifier_event.delivery_timestamp IS 'When this row was last delivered from the digital product.';
COMMENT ON COLUMN coco_inventory__serialised_product_identifiers.identifier_event.processing_status IS 'delivered (waiting for the subscriber), processed, or failed. Set back to delivered to reprocess the row.';
COMMENT ON COLUMN coco_inventory__serialised_product_identifiers.identifier_event.processing_timestamp IS 'When the subscriber last processed this row, successfully or not.';
COMMENT ON COLUMN coco_inventory__serialised_product_identifiers.identifier_event.processing_message IS 'Why processing failed, or any note the subscriber records.';

GRANT ALL ON ALL TABLES IN SCHEMA coco_inventory__serialised_product_identifiers TO egeria_admin, egeria_user, airflow_user;

