GRANT ALL ON SCHEMA coco_products__new_product_definitions TO egeria_admin, egeria_user, airflow_user;
COMMENT ON SCHEMA coco_products__new_product_definitions IS 'Subscription of Coco Product Management (Coco core, System::cocoProducts) to the digital product New Product Definitions (DigitalProduct::Coco::Product Definitions): a copy of the product''s data set coco_data_hub.new_product_definitions delivered for this subscriber. Basis: Product Master Data depends on it (new product definition).';

CREATE TABLE IF NOT EXISTS coco_products__new_product_definitions.candidate_product_definition (
  product_code              varchar(20) NOT NULL,
  candidate_identifier      varchar(40) NOT NULL,
  product_name              varchar(120) NOT NULL,
  formulation_identifier    varchar(40) NOT NULL,
  active_ingredient_name    varchar(120) NOT NULL,
  product_strength          varchar(40),
  clinical_trial_identifier varchar(40),
  candidate_handover_date   date NOT NULL,
  delivery_identifier       varchar(100) NOT NULL,
  delivery_timestamp        timestamptz NOT NULL DEFAULT now(),
  processing_status         varchar(20) NOT NULL DEFAULT 'delivered',
  processing_timestamp      timestamptz,
  processing_message        text,
  CONSTRAINT candidate_product_definition_pk PRIMARY KEY (product_code)
);
COMMENT ON TABLE coco_products__new_product_definitions.candidate_product_definition IS 'One row per product candidate handed over from development. Delivered from coco_data_hub.new_product_definitions.candidate_product_definition.';
COMMENT ON COLUMN coco_products__new_product_definitions.candidate_product_definition.product_code IS 'The product code assigned on handover.';
COMMENT ON COLUMN coco_products__new_product_definitions.candidate_product_definition.candidate_identifier IS 'The development identifier of the candidate.';
COMMENT ON COLUMN coco_products__new_product_definitions.candidate_product_definition.product_name IS 'The proposed product name.';
COMMENT ON COLUMN coco_products__new_product_definitions.candidate_product_definition.formulation_identifier IS 'The formulation developed.';
COMMENT ON COLUMN coco_products__new_product_definitions.candidate_product_definition.active_ingredient_name IS 'The active ingredient.';
COMMENT ON COLUMN coco_products__new_product_definitions.candidate_product_definition.product_strength IS 'The strength.';
COMMENT ON COLUMN coco_products__new_product_definitions.candidate_product_definition.clinical_trial_identifier IS 'The trial that supports the product.';
COMMENT ON COLUMN coco_products__new_product_definitions.candidate_product_definition.candidate_handover_date IS 'When development handed the definition over.';
COMMENT ON COLUMN coco_products__new_product_definitions.candidate_product_definition.delivery_identifier IS 'The delivery (for example the pipeline run) that last wrote this row.';
COMMENT ON COLUMN coco_products__new_product_definitions.candidate_product_definition.delivery_timestamp IS 'When this row was last delivered from the digital product.';
COMMENT ON COLUMN coco_products__new_product_definitions.candidate_product_definition.processing_status IS 'delivered (waiting for the subscriber), processed, or failed. Set back to delivered to reprocess the row.';
COMMENT ON COLUMN coco_products__new_product_definitions.candidate_product_definition.processing_timestamp IS 'When the subscriber last processed this row, successfully or not.';
COMMENT ON COLUMN coco_products__new_product_definitions.candidate_product_definition.processing_message IS 'Why processing failed, or any note the subscriber records.';

CREATE TABLE IF NOT EXISTS coco_products__new_product_definitions.product_presentation (
  pack_code            varchar(20) NOT NULL,
  product_code         varchar(20) NOT NULL,
  pack_description     text NOT NULL,
  pack_quantity        integer NOT NULL,
  delivery_identifier  varchar(100) NOT NULL,
  delivery_timestamp   timestamptz NOT NULL DEFAULT now(),
  processing_status    varchar(20) NOT NULL DEFAULT 'delivered',
  processing_timestamp timestamptz,
  processing_message   text,
  CONSTRAINT product_presentation_pk PRIMARY KEY (pack_code)
);
COMMENT ON TABLE coco_products__new_product_definitions.product_presentation IS 'One row per presentation the product will be supplied in. Delivered from coco_data_hub.new_product_definitions.product_presentation.';
COMMENT ON COLUMN coco_products__new_product_definitions.product_presentation.pack_code IS 'The presentation''s pack code.';
COMMENT ON COLUMN coco_products__new_product_definitions.product_presentation.product_code IS 'The product code assigned on handover.';
COMMENT ON COLUMN coco_products__new_product_definitions.product_presentation.pack_description IS 'The presentation.';
COMMENT ON COLUMN coco_products__new_product_definitions.product_presentation.pack_quantity IS 'Units per pack.';
COMMENT ON COLUMN coco_products__new_product_definitions.product_presentation.delivery_identifier IS 'The delivery (for example the pipeline run) that last wrote this row.';
COMMENT ON COLUMN coco_products__new_product_definitions.product_presentation.delivery_timestamp IS 'When this row was last delivered from the digital product.';
COMMENT ON COLUMN coco_products__new_product_definitions.product_presentation.processing_status IS 'delivered (waiting for the subscriber), processed, or failed. Set back to delivered to reprocess the row.';
COMMENT ON COLUMN coco_products__new_product_definitions.product_presentation.processing_timestamp IS 'When the subscriber last processed this row, successfully or not.';
COMMENT ON COLUMN coco_products__new_product_definitions.product_presentation.processing_message IS 'Why processing failed, or any note the subscriber records.';

CREATE TABLE IF NOT EXISTS coco_products__new_product_definitions.product_specification (
  product_code                varchar(20) NOT NULL,
  test_code                   varchar(40) NOT NULL,
  specification_minimum_value varchar(60),
  specification_maximum_value varchar(60),
  test_unit                   varchar(20),
  delivery_identifier         varchar(100) NOT NULL,
  delivery_timestamp          timestamptz NOT NULL DEFAULT now(),
  processing_status           varchar(20) NOT NULL DEFAULT 'delivered',
  processing_timestamp        timestamptz,
  processing_message          text,
  CONSTRAINT product_specification_pk PRIMARY KEY (product_code, test_code)
);
COMMENT ON TABLE coco_products__new_product_definitions.product_specification IS 'One row per specification limit the product must meet on release. Delivered from coco_data_hub.new_product_definitions.product_specification.';
COMMENT ON COLUMN coco_products__new_product_definitions.product_specification.product_code IS 'The product code assigned on handover.';
COMMENT ON COLUMN coco_products__new_product_definitions.product_specification.test_code IS 'The release test.';
COMMENT ON COLUMN coco_products__new_product_definitions.product_specification.specification_minimum_value IS 'The lower limit.';
COMMENT ON COLUMN coco_products__new_product_definitions.product_specification.specification_maximum_value IS 'The upper limit.';
COMMENT ON COLUMN coco_products__new_product_definitions.product_specification.test_unit IS 'The unit.';
COMMENT ON COLUMN coco_products__new_product_definitions.product_specification.delivery_identifier IS 'The delivery (for example the pipeline run) that last wrote this row.';
COMMENT ON COLUMN coco_products__new_product_definitions.product_specification.delivery_timestamp IS 'When this row was last delivered from the digital product.';
COMMENT ON COLUMN coco_products__new_product_definitions.product_specification.processing_status IS 'delivered (waiting for the subscriber), processed, or failed. Set back to delivered to reprocess the row.';
COMMENT ON COLUMN coco_products__new_product_definitions.product_specification.processing_timestamp IS 'When the subscriber last processed this row, successfully or not.';
COMMENT ON COLUMN coco_products__new_product_definitions.product_specification.processing_message IS 'Why processing failed, or any note the subscriber records.';

GRANT ALL ON ALL TABLES IN SCHEMA coco_products__new_product_definitions TO egeria_admin, egeria_user, airflow_user;

