COMMENT ON SCHEMA buc_veeva_qms__product_master_data IS 'Subscription of Veeva Vault QMS (Bucharest, SoftwareServer::SYS-002::Veeva Vault QMS) to the digital product Product Master Data (DigitalProduct::Coco::Product Master Data): a copy of the product''s data set coco_data_hub.product_master_data delivered for this subscriber. Basis: Batch Certification Decisions depends on it (product and market requirements).';

CREATE TABLE IF NOT EXISTS buc_veeva_qms__product_master_data.product_definition (
  product_code            varchar(20) NOT NULL,
  product_name            varchar(120) NOT NULL,
  product_description     text,
  product_type            varchar(40) NOT NULL,
  active_ingredient_name  varchar(120) NOT NULL,
  product_strength        varchar(40),
  product_current_status  varchar(20) NOT NULL,
  product_current_version varchar(20) NOT NULL,
  delivery_identifier     varchar(100) NOT NULL,
  delivery_timestamp      timestamptz NOT NULL DEFAULT now(),
  processing_status       varchar(20) NOT NULL DEFAULT 'delivered',
  processing_timestamp    timestamptz,
  processing_message      text,
  CONSTRAINT product_definition_pk PRIMARY KEY (product_code)
);
COMMENT ON TABLE buc_veeva_qms__product_master_data.product_definition IS 'One row per product, the attributes that identify it and describe what it is. Delivered from coco_data_hub.product_master_data.product_definition.';
COMMENT ON COLUMN buc_veeva_qms__product_master_data.product_definition.product_code IS 'The company''s unique code for the product.';
COMMENT ON COLUMN buc_veeva_qms__product_master_data.product_definition.product_name IS 'The product''s name as it appears on the label.';
COMMENT ON COLUMN buc_veeva_qms__product_master_data.product_definition.product_description IS 'What the product is and what it treats.';
COMMENT ON COLUMN buc_veeva_qms__product_master_data.product_definition.product_type IS 'Whether the product is a standard, personalised or investigational treatment.';
COMMENT ON COLUMN buc_veeva_qms__product_master_data.product_definition.active_ingredient_name IS 'The active ingredient responsible for the therapeutic effect.';
COMMENT ON COLUMN buc_veeva_qms__product_master_data.product_definition.product_strength IS 'The concentration or potency of the active ingredient.';
COMMENT ON COLUMN buc_veeva_qms__product_master_data.product_definition.product_current_status IS 'Whether the product is in development, marketed, suspended or withdrawn.';
COMMENT ON COLUMN buc_veeva_qms__product_master_data.product_definition.product_current_version IS 'The version of the product definition consuming systems should hold.';
COMMENT ON COLUMN buc_veeva_qms__product_master_data.product_definition.delivery_identifier IS 'The delivery (for example the pipeline run) that last wrote this row.';
COMMENT ON COLUMN buc_veeva_qms__product_master_data.product_definition.delivery_timestamp IS 'When this row was last delivered from the digital product.';
COMMENT ON COLUMN buc_veeva_qms__product_master_data.product_definition.processing_status IS 'delivered (waiting for the subscriber), processed, or failed. Set back to delivered to reprocess the row.';
COMMENT ON COLUMN buc_veeva_qms__product_master_data.product_definition.processing_timestamp IS 'When the subscriber last processed this row, successfully or not.';
COMMENT ON COLUMN buc_veeva_qms__product_master_data.product_definition.processing_message IS 'Why processing failed, or any note the subscriber records.';

CREATE TABLE IF NOT EXISTS buc_veeva_qms__product_master_data.pack_configuration (
  pack_code             varchar(20) NOT NULL,
  product_code          varchar(20) NOT NULL,
  pack_description      text,
  pack_quantity         integer NOT NULL,
  pack_destination_code varchar(8) NOT NULL,
  pack_serialised_flag  boolean NOT NULL,
  delivery_identifier   varchar(100) NOT NULL,
  delivery_timestamp    timestamptz NOT NULL DEFAULT now(),
  processing_status     varchar(20) NOT NULL DEFAULT 'delivered',
